INSERT INTO public.answer (question_id, clone_id, answer_date, text, vector) VALUES (1174, 2, '2024-02-27 13:01:23+00', 'I played a lot of sports when I was younger and although I don''t play in organized sports right now, I still train as though I were. Maybe not intensely, but physical fitness was... the importance of physical fitness was imbued in me at a young age. And so it''s been fairly easy to at least try and exercise pretty much my whole life. So I''ll jog and I''ll lift and if I have some work to do around the house, I can turn that into an exercise routine as well.', '[-0.0105220135,0.04026803,-0.021385282,0.009466653,0.06921147,0.02422907,-0.0013800269,0.040621925,0.007450723,0.016974252,-0.00046211548,-0.004057137,0.028589543,0.030712904,0.019982347,-0.0050461427,0.013852404,-0.029853448,-0.011653209,-0.015495482,0.08604669,0.014636027,0.0008483966,-0.04509615,-0.022295294,-0.03523769,0.026693685,-0.0045911367,-0.02757842,0.005365279,0.0455006,-0.0035736929,-0.058240768,-0.024721993,0.08190108,-0.033417664,0.015065754,-0.013738654,0.056269076,0.0066671018,0.047295347,-0.019881234,0.0071347468,0.016001044,-0.022244738,0.0055706636,0.021865565,0.0062974095,-0.0152047835,0.016089518,-0.030965686,0.0045216223,0.014673944,0.072902076,0.020677496,0.003371468,-0.032583486,-0.010395623,-0.064560294,0.028058704,0.01713856,0.01512895,0.027477307,0.037234657,-0.020146655,0.023319058,0.014977281,0.007880451,-0.005450593,-0.03212848,0.0054031964,-0.04898898,0.032153755,0.047548126,-0.0455006,-0.008866297,-0.040444978,-0.0057728887,0.04095054,0.04603144,0.04562699,-0.0059751137,0.016038962,0.03786661,-0.03842273,-0.021220975,-0.0353388,-0.017871624,-0.01806121,0.004714368,0.01808649,-0.0198054,-0.026314514,-0.0022529117,0.03971191,-0.0051188176,-0.0069767586,0.01698689,0.029095106,-0.012676973,0.01579882,0.014711861,0.019994985,-0.008739907,0.037310492,0.019919151,-0.0052610068,-0.012449469,-0.04150666,-0.02674424,-0.052123465,-0.021107223,0.0068440484,0.0028437874,