INSERT INTO public.answer (question_id, clone_id, answer_date, text, vector) VALUES (1175, 2, '2024-02-27 13:01:23+00', 'I guess my favorite memory from my childhood would be swimming in our pool with my brothers. We were fortunate enough to have an underground pool and I had a lot of fun swimming with them. I mostly swam with my brother Chris, but on occasion my brothers Tim and Casey would swim with us and that was especially fun.', '[0.015764514,-0.03724047,0.021580435,0.019641794,0.014150915,-0.028789392,0.011602821,0.04492538,-0.029346606,0.013431179,0.008567166,-0.0012131013,0.01545108,0.024819242,0.015427863,0.025724715,0.027814267,-0.027466008,-0.055117752,-0.01656551,-0.0014859041,0.04706137,0.0072089564,-0.014255392,0.014615259,-0.065333344,0.0007291668,0.0038105312,-0.02769818,0.019038146,-0.028441133,-0.0018094945,-0.037263688,0.020082923,0.07745275,0.012699836,0.026885577,-0.008334993,-0.007069653,0.026189059,0.05665009,-0.0036480105,-0.02423881,-0.001577322,-0.027001662,0.010691544,0.0025626041,-0.005200664,0.0030501664,0.021534,-0.017587068,0.020791048,-0.010151743,0.02820896,0.001067268,0.010958542,0.00065661286,0.015160865,-0.041512445,-0.014905475,-0.036474302,0.00567952,-0.027303487,0.0072437823,0.011579604,0.02811609,0.0032823388,-0.017378112,0.021766173,0.024285244,-0.002706261,0.018771147,0.013883916,-0.0044199843,-0.030600337,-0.0063034836,-0.00152073,-0.05623218,0.029578777,0.014557216,0.036056392,-0.010993368,-0.0077487575,0.018457714,-0.06965175,0.010668327,0.016240466,-0.015218908,0.056278616,0.011451909,0.022985078,-0.0001440195,-0.0010542083,-0.040328365,-0.013315094,-0.02272969,-0.027976787,-0.035801,-0.001558458,0.012131014,0.025051413,-0.033757884,-0.01757546,-0.031111116,0.0058942796,0.002487148,-0.005691129,0.06468326,0.0080331685,0.026723055,-0.09899836,-0.054328367,-0.063058056,0.008485905,-0.034268662,0.061897192,-0.01266501,-0.02693201,-0.005995855,0.024633503,0.042626873,-0.023704814,0.021917084,-0.04053732,0.012049753,-0.00073