INSERT INTO public.answer (question_id, clone_id, answer_date, text, vector) VALUES (1251, 2, '2024-09-02 20:39:03.27024+00', 'During covid I couldn''t find a job. I survived by doing doordash. At first it was humiliating but I overcame that and it was I guess you might say the best of times and the worst of times. I grew tremendously. I fixed my own car when it broke down. Weirdly I felt more free doing that than I ever have as a doordasher. Plus I got a front row seat to all of the covid hysteria.', '[0.050687626,-0.0018624237,-0.042940933,-0.010964169,-0.016223505,-0.015258262,0.03487249,0.020888845,-0.002256874,-0.02281933,0.0049252133,0.0028771663,-0.04437642,-0.0101598,0.0012142878,0.02848704,-0.018587112,-0.012084098,-0.023326702,0.009974176,0.0020604222,-0.0068990113,0.021235343,0.011861349,0.010803295,-0.020109225,0.02510869,-0.043633927,0.01008555,-0.013327776,0.03361025,-0.03524374,-0.031580765,0.0088356845,-0.0019799853,0.06073605,-0.01047536,-0.003242226,-4.6357567e-05,0.005280992,0.0003727941,-0.039228458,0.051628117,-0.029180033,0.012275909,0.027670294,-0.048064142,-0.003480443,0.016273005,0.02075272,-0.029254284,0.04212419,-0.023413327,0.09048533,0.02680405,0.022386208,-0.018104492,0.057667073,0.0066143884,0.01076617,-0.016582377,0.026111057,0.019861728,-0.009732866,0.0042353123,0.01939148,-0.0027379484,-0.0015453167,-0.014689016,-0.0004338952,0.0070103854,0.030244276,-0.046702903,0.008124127,0.017931242,0.058261067,-0.005166524,0.0008500015,0.02965028,-0.0023311235,0.022126336,-0.0002799823,-0.026111057,-0.033239003,-0.01817874,-0.002423935,-0.0337835,0.031704515,0.017733244,-0.002550778,-0.019997852,0.019143984,0.016000757,-0.016644252,0.048039395,0.01944098,-0.041480694,0.011032231,-0.061973542,0.0039568767,0.013179277,-0.017733244,-0.03274401,-0.035515986,0.008278813,-0.0035423175,-0.022621332,0.0110693555,-0.01567901,0.047668148,-0.06340903,-0.043336928,-0.045762412,0.02960078,-0.005633677,-0.019329607,-0.015641885,0.011323041,0.010506297,0.0258