INSERT INTO public.answer (question_id, clone_id, answer_date, text, vector) VALUES (1307, 2, '2024-02-27 13:01:23+00', 'I guess when it comes to mental health, I''m just trying to stay positive. So far I''m able to do that by exercising and taking good care of myself. But I think if I were to adopt a defeatist attitude, my mental health would nose dive real quick. I''m concerned about my mental health, but I''m able to manage it by staying strong, I guess, and staying positive and working on my physical health.', '[0.014569501,8.2798404e-05,0.025179768,0.06677587,0.022838026,0.02217413,-0.020472141,0.01786484,0.0070372988,0.014617785,-0.014666068,-0.018890861,-0.01857702,-0.017031953,0.013579693,0.02132917,0.0021757686,0.024648651,-0.00074084767,0.06354089,0.038819816,0.036767773,0.02205342,-0.013398631,-0.01613871,0.003512614,-0.009505785,0.01396596,-0.024141677,0.036067665,-0.020351432,-0.017768273,-0.036622923,0.020448,0.020930834,0.023031158,-0.025686743,-0.025566036,0.02735252,0.0039169868,-0.014424652,-0.021703366,0.018106258,0.002804961,-0.02909072,-0.010724939,0.03473987,-0.018263178,0.015861081,-0.033943195,-0.085751235,0.063734025,0.036791913,0.08068148,0.023405354,0.03686434,-0.020918762,-0.0063190837,-0.038819816,0.012795089,0.05934024,-0.013314134,0.03372592,0.04316532,-0.00951182,0.014678139,0.0048283353,-0.025469469,-0.02665241,-0.029476987,0.019989308,-0.017502716,0.034619164,0.0137848975,-0.022910452,-0.048331637,0.058809124,-0.03196358,0.056346674,-0.008184028,-0.016307702,0.016935386,-0.027135244,0.025566036,0.01843217,-0.040123466,-0.03935093,-0.029259712,-0.018770153,0.0078339735,-0.012040661,0.024986634,-0.06552051,-0.0055525857,0.045313925,-0.021353312,-0.012396751,0.043672293,-0.012161369,-0.010779259,0.0036846234,0.027111102,0.0029965856,-0.02981497,0.02274146,0.017961407,0.045555342,-0.043889567,-0.031746306,0.019663395,-0.09656671,-0.0059147105,-0.010133469,0.02089462,0.0003249696,-0.029983962,-0.033146523,0.07232846,0.017599283,0.0067717