INSERT INTO public.answer (question_id, clone_id, answer_date, text, vector) VALUES (1389, 2, '2024-02-27 13:01:23+00', 'Exercise, keep my home clean, get outside more, and try to keep busy. I find I''m much happier at the end of the day if I got a lot of work done. I feel bad at the end of the day if I eat junk food and don''t get any work done. So I try to avoid that.', '[-0.0133756595,-0.014100695,-0.033976674,0.030251492,0.010519269,0.0065190713,0.0068003354,0.0102130035,0.026601313,0.021626066,0.0064003156,0.003022024,0.011469316,0.020601016,-0.0042877113,0.023338651,0.041102026,0.015225751,-0.002792325,0.031926576,0.036751814,0.003606428,-0.012381861,-0.008744181,0.01642581,-0.013013142,-0.0062003057,0.001865717,0.08070398,-0.013350658,-0.017213348,-0.01034426,-0.017363356,-0.023876177,0.056452785,0.030451503,-0.016925834,-0.031051531,0.03585177,-0.019550964,0.028876424,-0.05985295,0.01925095,-0.011888086,0.03327664,-0.04627728,-0.012313107,0.020175995,0.0113130575,-0.0011703703,-0.016075794,0.040426992,0.012081846,-4.8464302e-05,0.020238498,-0.043052122,-0.036551803,-0.014975739,-0.06330312,0.054052666,0.055452734,-0.016250802,0.034401696,0.04627728,-0.022763623,-0.019938484,0.017375857,-0.03585177,-0.022813626,-0.01885093,-0.024763722,-0.010619273,0.050927512,0.0162008,-0.017700873,-0.08605424,0.04035199,-0.0527026,0.0670533,0.0016844581,-0.019738473,-0.005678405,-0.011406813,0.049602445,0.012294357,-0.09755481,-0.034401696,-0.03400168,-0.04970245,-0.023426155,0.0146132205,-0.0079441415,-0.064303175,0.015475763,0.042952117,0.021713572,-0.047527343,0.026501307,0.024913728,-0.0010406764,0.037876867,0.007931641,0.041827064,-0.009475468,-0.0066440776,-0.016788328,-0.0124818655,-0.03565176,0.013675675,-0.01541326,-0.060702994,0.008344161,-0.03610178,0.01540076,-0.039651956,0.00027559954,-0.015500764,0.02515124,0.018538414,-0.020963535,-0.004300212,0.058352876,-0.059652943,-0.039076928,-0.009200454,0.03505173,0.018000888,-0.013400661,-0.040451996,-0.032801617,0.02