INSERT INTO public.answer (question_id, clone_id, answer_date, text, vector) VALUES (1208, 2, '2024-02-27 13:01:23+00', 'Yes, I tried getting custody of my daughter and I was using my sister as my main advocate. What I didn''t know is that my sister was going to stab me in the back and tell a bunch of lies about me and that pretty much changed my entire perspective on humanity and actually the government as well because what I saw was how willing and ready the government was to accept any lie, any accusation at all that they could use to exercise their quote unquote justice system, which is anything but.', '[-0.0075356644,-0.019153146,-0.05144347,0.0798278,-0.0529506,-0.006015972,-0.0030613635,-0.015422992,-0.019894153,0.008188755,0.058828417,-0.0063173985,-0.016779412,0.035317145,0.029012308,0.010235944,0.085454434,-0.016201679,-0.046118263,-0.026123635,-0.002127255,0.071940474,0.041471273,-0.02040909,-0.015510908,-0.038306292,0.08374635,-0.026801845,0.021263132,0.038733315,0.022720028,-0.02579709,-0.033483468,-0.0031477096,-0.008634615,0.010788559,-0.019014992,-0.071538575,0.054005593,0.0022151712,0.034638938,-0.016452868,0.03682428,0.009061636,-0.004825965,0.002537007,0.03722618,0.031976335,-0.017872084,-0.010122909,-0.05857723,0.034865007,0.028635524,0.08731323,-0.0060034124,0.005730245,-0.019077789,0.032654546,-0.03328252,-0.02692744,0.0399139,0.023812698,0.013199972,0.043455664,0.00014953583,-0.04868039,-0.0017300629,0.016729174,-0.00070607604,0.005497895,0.019605286,-0.007881049,-0.010443174,0.029263496,-0.013049259,0.02131337,0.05026288,0.071739525,0.0036610768,0.010706923,0.01661614,0.031951215,-0.016201679,0.029916586,0.017671132,0.03903474,-0.041471273,0.0147699015,-0.06556028,-0.023209846,-0.045038152,0.054005593,0.0034287272,0.019215943,0.046068028,0.021300811,-0.058727942,0.026852082,0.038205817,-0.01706828,0.011818433,0.03433751,0.0014623898,-0.0015667902,0.04081818,-0.021401286,0.030444084,-0.022971217,0.05139323,0.00919351,-0.023498712,-0.0278066,-0