INSERT INTO public.answer (question_id, clone_id, answer_date, text, vector) VALUES (1333, 2, '2024-09-02 21:18:19.38599+00', 'In terms of taste and convenience it''s hard to beat a banana. Oranges might be better if they weren''t so hard to peel. But in terms of appearance I''d say dragon fruit hands down. Whenever I see a dragon fruit I marvel at how evolution created such a colorful fruit. Whatever animal eats it in the wild must be attracted to those colors. ....bananas have their own wrappers...', '[0.034422256,-0.017683346,-0.013433378,0.060294867,0.058058042,-0.029004168,0.054280292,0.02331269,0.013222123,0.013097854,0.0068782377,-0.005647984,0.0023502198,0.005592063,0.0038926972,-0.009407093,0.017322969,-0.015073717,0.017646065,-0.0006054185,0.0278609,0.009500294,0.030917896,0.044612236,0.012973586,0.024319261,-0.007717047,0.04085934,0.01876448,-0.03322928,0.01887632,-0.012290112,-0.026394539,-0.031663503,-0.030221995,0.014812754,0.015297399,-0.013744049,-0.007698407,0.044388555,0.03728042,0.05249083,0.012606995,0.010152701,0.06044399,0.036211714,-0.009699123,0.0041381265,-0.040685367,0.007468511,-0.03700703,0.012488941,-0.016328825,0.00018999423,0.021162853,-0.029724922,-0.052242298,-0.0044239433,-0.032284845,0.049806643,-0.0159933,-0.00035008646,-0.016689202,0.046923622,0.0037746425,0.019037869,-0.011072285,0.009394666,0.017546652,0.0220203,-0.011743332,0.023523945,-0.0076052058,-0.0065054335,0.011774399,-0.011650131,0.019385818,0.0052969265,-0.0068658106,-0.004809174,-0.01794431,-0.015086143,-0.015148277,-0.011786826,0.02451809,-0.027214708,0.03178777,-0.00012611267,-0.021237412,-0.016763762,0.022256412,-0.04933442,-0.022256412,-0.013321537,-0.053733513,0.07108133,-0.033179574,0.03377606,-0.02152323,0.004470544,0.015769618,-0.014253547,-0.037031885,0.0347205,0.029774629,0.023213275,0.030371116,0.004343169,-0.022082435,0.016440665,0.015235265,-0.016465519,-0.0070025055,0.049085885,0.0015727677,-0.02572349,-0.01758393,-0.03536669,0.04207717,-0.080277175,0.0